import {SchoolTHREE as THREE,schoolBox,schoolMaterial,schoolRod} from './core.js?v=76a';
// Depth, posts and layered roofs follow the v223 rounded prop / open-pavilion construction kit.
export function addLivingFacilities(parent,kit,{places=null,accent=0x8abec3}={}){const motions=[],root=new THREE.Group();root.name='Schoolbus-style living facility details';parent.add(root);const box=(w,h,d,x,y,z,c,p=root)=>{const m=new THREE.Mesh(schoolBox(w,h,d),schoolMaterial(c));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;p.add(m);return m;};
 if(places){for(const [i,p]of places.entries()){if(!p.width||!p.depth)continue;const x=p.x+p.width*.33,z=p.z+p.depth*.5;const awning=new THREE.Group();awning.position.set(x,4.4,z+.25);root.add(awning);for(let j=0;j<5;j++)box(.38,.1,1.15,(j-2)*.38,0,0,j%2?0xfff2d5:accent,awning).rotation.x=-.13;box(2,.32,.1,0,-.14,.57,accent,awning);const flag=new THREE.Group();flag.position.set(p.x-p.width*.32,6.4,p.z);root.add(flag);schoolRod(new THREE.Vector3(),new THREE.Vector3(0,2,0),.035,schoolMaterial(0xc7b590),flag);const cloth=box(1.1,.58,.045,.55,1.65,0,[0xf2bd93,0x9ac7bd,0xc2b1dc][i%3],flag);motions.push({object:cloth,base:cloth.rotation.y,kind:'flag',phase:i});motions.push({object:awning,base:0,kind:'awning',phase:i});}}
 else{for(const side of [-1,1]){const g=new THREE.Group();g.position.set(side*16,0,-15);root.add(g);for(const x of [-3.4,3.4])for(const z of [-2.2,2.2])box(.22,4.5,.22,x,2.25,z,0xc8ae89,g);for(let i=-4;i<=4;i++)box(.15,.18,5.2,i*.85,4.6,0,0xacc9be,g);for(const z of [-2.4,2.4])box(7.8,.25,.16,0,4.45,z,accent,g);for(let i=0;i<4;i++){const m=box(.55,.12,.18,(i-1.5)*1.4,4.1,0,0xf0cd87,g);motions.push({object:m,base:0,kind:'mobile',phase:i+side});}kit.labelBoard?.('Sit, talk and play',0,3.7,-2.35,4,g);}}
 return {root,motions};}
export function tickLivingFacilities(items,t,reduced=false){for(const a of items||[]){const v=reduced?0:Math.sin(t*(a.kind==='flag'?1.6:.8)+a.phase);if(a.kind==='flag')a.object.rotation.y=a.base+v*.16;else a.object.rotation.z=a.base+v*(a.kind==='awning'?.012:.16);}}
